const UUID={service:'6f3a0001-8f7a-4b3d-9d64-4553504d4f52',settings:'6f3a0002-8f7a-4b3d-9d64-4553504d4f52',events:'6f3a0003-8f7a-4b3d-9d64-4553504d4f52'};
const $=s=>document.querySelector(s),enc=new TextEncoder(),dec=new TextDecoder();
let device,settingsChar,eventChar,connected=false;
const connect=$('#connect'),send=$('#send'),save=$('#save'),refresh=$('#refresh'),history=$('#history'),message=$('#message');
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(t.x);t.x=setTimeout(()=>t.classList.remove('show'),2200)}
function setConnected(on){connected=on;connect.classList.toggle('online',on);connect.querySelector('span').textContent=on?'切断':'接続する';$('#state').textContent=on?'ONLINE':'OFFLINE';$('#state').classList.toggle('online',on);[send,save,refresh,history].forEach(x=>x.disabled=!on)}
function textOf(e){return dec.decode(e.target.value)}
function esc(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
function now(){return new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function clearChat(){const box=$('#timeline');box.innerHTML='<p class="empty">接続後の送受信メッセージをここに表示します。</p>';$('#lastSeen').textContent='—'}
function trimMessages(){const rows=[...document.querySelectorAll('#timeline .message-row')];while(rows.length>5)rows.shift().remove()}
function parseMessage(t){if(t.startsWith('RX ')){const p=t.split(' ');return{kind:'rx',sender:p[1],body:p.slice(2).join(' ')}}if(t.startsWith('TX ')&&!['TX ACK','TX RETRY','TX FAILED','TX CANCELLED'].includes(t))return{kind:'tx',sender:'自分',body:t.slice(3)};return null}
function addMessage(kind,sender,body){const box=$('#timeline'),time=now();box.querySelector('.empty')?.remove();const row=document.createElement('div');row.className=`message-row ${kind}`;row.innerHTML=`<div class="bubble"><span class="sender">${esc(sender)}</span><p>${esc(body)}</p><time>${time}</time></div>`;box.append(row);trimMessages();box.scrollTop=box.scrollHeight;$('#lastSeen').textContent=time}
function addEvent(text){const msg=parseMessage(text);if(msg)return addMessage(msg.kind,msg.sender,msg.body);if(!/FAIL|ERROR|LOW|CANCELLED/.test(text))return;const box=$('#timeline'),time=now();box.querySelector('.empty')?.remove();const p=document.createElement('div');p.className='system-event error';p.innerHTML=`<span>${esc(text)}</span><time>${time}</time>`;box.append(p);box.scrollTop=box.scrollHeight}
async function write(command){if(!settingsChar)throw Error('未接続です');const data=enc.encode(command);if(settingsChar.writeValueWithResponse)await settingsChar.writeValueWithResponse(data);else await settingsChar.writeValue(data)}
async function readStatus(){const value=await settingsChar.readValue();parseStatus(dec.decode(value))}
function parseStatus(text){const pairs=Object.fromEntries([...text.matchAll(/([A-Z_]+)=([^\s]+)/g)].map(m=>[m[1],m[2]]));document.querySelectorAll('[data-command]').forEach(el=>{const v=pairs[el.dataset.command];if(v===undefined)return;el.type==='checkbox'?el.checked=v==='1':el.value=v})}
async function doConnect(){if(connected){device.gatt.disconnect();return}if(!window.isSecureContext)return toast('HTTPSで開いてください');if(!navigator.bluetooth)return toast('Web Bluetoothを有効にしてください');try{device=await navigator.bluetooth.requestDevice({filters:[{services:[UUID.service]}]});device.addEventListener('gattserverdisconnected',()=>{setConnected(false);toast('切断しました')},{once:true});const server=await device.gatt.connect(),service=await server.getPrimaryService(UUID.service);settingsChar=await service.getCharacteristic(UUID.settings);eventChar=await service.getCharacteristic(UUID.events);await settingsChar.startNotifications();await eventChar.startNotifications();settingsChar.addEventListener('characteristicvaluechanged',e=>{const t=textOf(e);if(t.startsWith('OK CW_'))parseStatus(t);else if(!t.startsWith('OK '))addEvent(t)});eventChar.addEventListener('characteristicvaluechanged',e=>addEvent(textOf(e)));$('#deviceName').textContent=device.name||'ESPmorse';$('#support').textContent='暗号化BLE接続（PIN不要）';clearChat();setConnected(true);await readStatus();toast('ESPmorseに接続しました')}catch(e){console.error(e);setConnected(false);toast(`${e.name}: ${e.message}`)}}
connect.addEventListener('click',doConnect);
message.addEventListener('input',()=>$('#counter').textContent=`${message.value.length} / 31`);
send.addEventListener('click',async()=>{const s=message.value.trim().toUpperCase();if(!s)return;try{await write(`SEND=${s}`);message.value='';message.dispatchEvent(new Event('input'));toast('送信キューに追加しました')}catch(e){toast(e.message)}});
history.addEventListener('click',()=>{clearChat();toast('表示を消去しました')});
refresh.addEventListener('click',()=>readStatus().catch(e=>toast(e.message)));
save.addEventListener('click',async()=>{try{for(const el of document.querySelectorAll('[data-command]')){await write(`${el.dataset.command}=${el.type==='checkbox'?(el.checked?1:0):el.value}`);await new Promise(r=>setTimeout(r,90))}toast('設定を保存しました')}catch(e){toast(e.message)}});
$('#support').textContent=navigator.bluetooth?'Brave / Chrome / Edge対応':'Web Bluetooth対応ブラウザで開いてください';if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});setConnected(false);
